@Nullable
private String escapeEl(@Nullable String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    final Matcher m = ESCAPE_PATTERN.matcher(s);
    final StringBuffer sb = new StringBuffer(s.length() + 16);
    while (m.find()) {
        m.appendReplacement(sb, "\\\\\\${");
    }
    m.appendTail(sb);
    return sb.toString();
}

