	value = value.toLowerCase().trim();

	// 二、SQL注入检测存在绕过风险 (普通文本校验)
	for (int i = 0; i < xssArr.length; i++) {
		if (isExistSqlInjectKeyword(value, xssArr[i])) {
			log.error(SqlInjectionUtil.SQL_INJECTION_KEYWORD_TIP, xssArr[i]);
			log.error(SqlInjectionUtil.SQL_INJECTION_TIP_VARIABLE, value);
			throw new JeecgSqlInjectionException(SqlInjectionUtil.SQL_INJECTION_TIP + value);
		}
	}

	// 三、SQL注入检测存在绕过风险 (正则校验)
	for (String regularOriginal : XSS_REGULAR_STR_ARRAY) {
		String regular = ".*" + regularOriginal + ".*";
		if (Pattern.matches(regular, value)) {
			log.error(SqlInjectionUtil.SQL_INJECTION_KEYWORD_TIP, regularOriginal);
			log.error(SqlInjectionUtil.SQL_INJECTION_TIP_VARIABLE, value);
			throw new JeecgSqlInjectionException(SqlInjectionUtil.SQL_INJECTION_TIP + value);
		}
	}
	return;
}

public function sanitize( $shortDesc ) {
	// Remove accidental formatting - descriptions are plaintext.
	$shortDesc = strip_tags( $shortDesc );
	// Unescape - clients are not necessarily HTML-based and using HTML tags as part of
	// the descript (i.e. with <nowiki> or such) should be possible.
	$shortDesc = html_entity_decode( $shortDesc, ENT_QUOTES, 'utf-8' );

	// Remove newlines, tabs and other weird whitespace
	$shortDesc = preg_replace( '/\s+/', ' ', $shortDesc );

	// Get rid of leading/trailing space - no valid usecase for it, easy for it to go unnoticed
	// in HTML, and clients might display the description in an environment that does not
	// ignore spaces like HTML does.
	return trim( $shortDesc );
}

const URL_PROTOCOL_REGEX = /^(?:(?:http|ftp|https|ws):?\/\/|\/\/)/;

export function isRemotePath(src: string) {
	return URL_PROTOCOL_REGEX.test(src) || src.startsWith('data:');
}

// XSS 관련 태그 제거
function clean_xss_tags($str, $check_entities=0, $is_remove_tags=0, $cur_str_len=0, $is_trim_both=1)
{
    if( $is_trim_both ){
        $str = trim($str);
    }

    if( $check_entities ){
        $str = str_replace(array('&amp;', '&lt;', '&gt;'), array('&amp;amp;', '&amp;lt;', '&amp;gt;'), $str);
    }

    // tab('\t'), formfeed('\f'), vertical tab('\v'), newline('\n'), carriage return('\r') 를 제거한다.
    $str = preg_replace("#[\t\f\v\n\r]#", '', $str);

    if( $is_remove_tags ){
        $str = strip_tags($str);
    }

    if( $cur_str_len ){
        $str = utf8_strcut($str, $cur_str_len, '');
    }

    $str_len = strlen($str);
    $i = 0;
    while($i <= $str_len){
        $result = preg_replace('#</*(?:applet|b(?:ase|gsound|link)|embed|frame(?:set)?|i(?:frame|layer)|l(?:ayer|ink)|meta|object|s(?:cript|tyle)|title|xml)[^>]*+>#i', '', $str);

        if( $check_entities ){
            $result = str_replace(array('&colon;', '&lpar;', '&rpar;', '&NewLine;', '&Tab;'), '', $result);
        }

        $result = preg_replace('#([^\p{L}]|^)(?:javascript|jar|applescript|vbscript|vbs|wscript|jscript|behavior|mocha|livescript|view-source)\s*:(?:.*?([/\\\;()\'">]|$))#ius',
                '$1$2', $result);

        if((string)$result === (string)$str) break;

        $str = $result;
        $i++;
    }

    return $str;
}

private function isSvg(string $filePath): bool
{
    // comprobamos la extensión
    if (strpos($filePath, '.svg') !== false) {
        return true;
    }

    // comprobamos mime
    if (strpos($this->getMime($filePath), 'image/svg') !== false) {
        return true;
    }

    return false;
}

private static final List<Pattern> xssPatterns = ListUtils.newArrayList(
		Pattern.compile("(<\\s*(script|link|style|iframe)([\\s\\S]*?)(>|<\\/\\s*\\1\\s*>))|(</\\s*(script|link|style|iframe)\\s*>)", Pattern.CASE_INSENSITIVE),
		Pattern.compile("\\s*(href|src)\\s*=\\s*(\"\\s*(javascript|vbscript):[^\"]+\"|'\\s*(javascript|vbscript):[^']+'|(javascript|vbscript):[^\\s]+)\\s*(?=>)", Pattern.CASE_INSENSITIVE),
		Pattern.compile("\\s*/?\\s*on[a-zA-Z]+\\s*=\\s*(['\"]?)(.*?)\\1(?=\\s|>|/>)", Pattern.CASE_INSENSITIVE),
		Pattern.compile("(eval\\((.*?)\\)|expression\\((.*?)\\))", Pattern.CASE_INSENSITIVE),
		Pattern.compile("^(javascript:|vbscript:)", Pattern.CASE_INSENSITIVE)
);
